package android.graphics; public class Region { public enum Op { DIFFERENCE,INTERSECT,UNION,XOR,REVERSE_DIFFERENCE,REPLACE } private Rect bounds=new Rect(); public Region(){} public Region(Rect r){bounds.set(r);} public Region(int l,int t,int r,int b){bounds.set(l,t,r,b);} public Region(Region r){bounds.set(r.bounds);} public boolean set(Rect r){bounds.set(r);return !isEmpty();} public boolean set(int l,int t,int r,int b){bounds.set(l,t,r,b);return !isEmpty();} public boolean set(Region r){return set(r.bounds);} public void setEmpty(){bounds.setEmpty();} public boolean isEmpty(){return bounds.isEmpty();} public boolean contains(int x,int y){return bounds.contains(x,y);} public Rect getBounds(){return new Rect(bounds);} public boolean getBounds(Rect r){r.set(bounds);return !isEmpty();} public boolean op(Rect r,Op o){if(o==Op.INTERSECT){if(!bounds.intersect(r))bounds.setEmpty();}else if(o==Op.REPLACE)bounds.set(r);else if(o==Op.UNION||o==Op.XOR)bounds.union(r);else if(o==Op.DIFFERENCE&&r.contains(bounds))bounds.setEmpty();return !isEmpty();} public boolean op(Region r,Op o){return op(r.bounds,o);} public boolean op(int l,int t,int r,int b,Op o){return op(new Rect(l,t,r,b),o);} public boolean setPath(Path p,Region clip){RectF f=new RectF();p.computeBounds(f,true);bounds.set((int)f.left,(int)f.top,(int)f.right,(int)f.bottom);return op(clip,Op.INTERSECT);} }